public sealed class Checkout(ShopDb db)
{
    public async Task<string> PlaceAsync(Order order, CancellationToken ct)
    {
        db.Orders.Add(order);
        // Ordering writes Billing's table and copies Billing's tax rule
        var invoice = new Invoice(order.Id, order.Net * 1.14m);
        db.Invoices.Add(invoice);
        await db.SaveChangesAsync(ct);
        return invoice.Number;
    }
}
// Every module reaches into every table: Billing can't change alone,
// and splitting it out later means untangling all of this first

// The module's public contract: one coarse call, no tables exposed
public interface IBilling
{
    Task<string> InvoiceAsync(Guid orderId, decimal net, CancellationToken ct);
}

// Tax rules and Billing's tables stay internal to this project
internal sealed class BillingModule(BillingDb db) : IBilling
{
    public async Task<string> InvoiceAsync(
        Guid orderId, decimal net, CancellationToken ct)
    {
        var invoice = Invoice.For(orderId, net); // the VAT rule lives here
        db.Invoices.Add(invoice);
        await db.SaveChangesAsync(ct);
        return invoice.Number;
    }
}

public static class BillingSetup
{
    public static IServiceCollection AddBilling(this IServiceCollection s) =>
        s.AddScoped<IBilling, BillingModule>();
}
